import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const c=JSON.parse('{"title":"IS373 student RAG guide","description":"Finish the existing individual RAG assignment with a small source-backed application, guided steps and AI coding prompts.","frontmatter":{"title":"IS373 student RAG guide","description":"Finish the existing individual RAG assignment with a small source-backed application, guided steps and AI coding prompts."},"headers":[],"relativePath":"students/index.md","filePath":"students/index.md","lastUpdated":1794376220000}'),s={name:"students/index.md"};function n(i,e,d,l,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="build-a-small-rag-system-you-can-explain" tabindex="-1">Build a small RAG system you can explain <a class="header-anchor" href="#build-a-small-rag-system-you-can-explain" aria-label="Permalink to &quot;Build a small RAG system you can explain&quot;">​</a></h1><p><strong>Start with one useful question, around five permitted documents, and a visible source-to-answer trace.</strong> You do not need to build Ordo Knowledge Lab or train a model to finish your IS373 independent project.</p><p>This is <strong>optional help</strong>, not a new assignment, grade, submission or required stack. The authoritative instructions are the <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/projects/individual.md" target="_blank" rel="noreferrer">IS373 individual RAG brief</a>, <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/handouts/database-rag-research.md" target="_blank" rel="noreferrer">research handout</a>, and Canvas.</p><p><strong>New here?</strong> <a href="./reference#your-first-15-minutes">Spend your first 15 minutes finding a real source passage</a>. No API key or model download needed.</p><h2 id="choose-your-next-step" tabindex="-1">Choose your next step <a class="header-anchor" href="#choose-your-next-step" aria-label="Permalink to &quot;Choose your next step&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where you are</th><th>Go here</th></tr></thead><tbody><tr><td>Unsure what to build</td><td><a href="./plan">Plan one question and small source set</a></td></tr><tr><td>Ready to implement</td><td><a href="./build">Build the smallest complete source-to-answer path</a></td></tr><tr><td>Want AI coding help</td><td><a href="./prompts">Copy a bounded agent prompt</a></td></tr><tr><td>Something doesn&#39;t work</td><td><a href="./stuck">Diagnose one failure at a time</a></td></tr><tr><td>Have an answer and need evidence</td><td><a href="./check">Run five evaluation questions</a></td></tr><tr><td>Want a safe, inspectable example</td><td><a href="./reference">Optional local retrieval lab</a></td></tr></tbody></table><h2 id="the-five-things-your-demo-should-show" tabindex="-1">The five things your demo should show <a class="header-anchor" href="#the-five-things-your-demo-should-show" aria-label="Permalink to &quot;The five things your demo should show&quot;">​</a></h2><ol><li><strong>Import:</strong> where the permitted sources came from and what was stored.</li><li><strong>Represent:</strong> how text becomes chunks/vectors or graph relationships with source IDs.</li><li><strong>Retrieve:</strong> which source IDs or graph paths a real question returned.</li><li><strong>Generate:</strong> how a real model used that evidence, with usable source references.</li><li><strong>Check:</strong> what happened on a missing-evidence question and what you improved.</li></ol><p>Research <strong>both vector and graph approaches</strong>, then justify implementing vector, graph or both. A keyword-only baseline or a mocked model is helpful for learning but is <strong>not</strong> the finished RAG application.</p><h2 id="keep-your-three-deliverables-separate" tabindex="-1">Keep your three deliverables separate <a class="header-anchor" href="#keep-your-three-deliverables-separate" aria-label="Permalink to &quot;Keep your three deliverables separate&quot;">​</a></h2><p>Your <strong>portfolio</strong> presents your professional direction and showcases the app. Your <strong>individual RAG app</strong> is this technical product. Your <strong>group system</strong> is a separate shared content workflow. Keep the existing individual and group project records; do not create another weekly report for this guide.</p><h2 id="pacing-from-the-course-guide" tabindex="-1">Pacing from the course guide <a class="header-anchor" href="#pacing-from-the-course-guide" aria-label="Permalink to &quot;Pacing from the course guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Course guide date (2026, Eastern)</th><th>Useful next result</th></tr></thead><tbody><tr><td>Plan</td><td>Nov 17, 1 p.m.</td><td>Reader, sources, chosen retrieval approach, evaluation questions</td></tr><tr><td>Build</td><td>Nov 24, 1 p.m.</td><td>Hosted small real import → retrieval → chat</td></tr><tr><td>Checked Release</td><td>Dec 3, 1 p.m.</td><td>Persistent hosted app, sources, actual checks, repeatable setup</td></tr><tr><td>Improve</td><td>Dec 10, 11:59 p.m.</td><td>Peer feedback, meaningful fix and retest</td></tr><tr><td>Demo</td><td>Dec 18</td><td>Explain the system and show your real evidence</td></tr></tbody></table><p>Use <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/course/milestones.md" target="_blank" rel="noreferrer">course milestones</a> and Canvas for official instructions. Dates here summarize the published guide, not a Canvas update.</p><p><strong>Start small. Show one working path. Be able to explain it.</strong></p>',15)])])}const m=t(s,[["render",n]]);export{c as __pageData,m as default};
